# Teach-first pattern lessons for every remaining unit (compact form).
# Example: (speaker, mood, scene, albanian, turkish, albanian target, turkish target)
#   make.py colours the target red (1) and the rest blue (0), so the learner sees which Turkish piece
#   becomes which Albanian piece.
# Drill:   (sentence with ___, options (correct first), turkish, why)


def P(id, unit, t, rule, ex, drills):
    return {"id": id, "unit": unit, "t": t, "rule": rule, "ex": ex, "drills": drills}


